def main():
    notes = json.load(open(os.path.join(HERE, "..", "data", "research.json"), encoding="utf-8"))
    by_key = {n["key"]: n for n in notes}
    out, used = {}, set()
    for name, (en, es) in ALTS.items():
        key, _, number = name.rpartition("-")
        n = by_key[key]
        assert 1 <= int(number) <= len(n["images"]), name
        out.setdefault(n["slug"], {})[str(int(number))] = {"en": en, "es": es}
        used.add(name)
    every = ["%s-%02d" % (n["key"], k) for n in notes for k in range(1, len(n["images"]) + 1)]
    without = [x for x in every if x not in used]
    with open(os.path.join(HERE, "alts.json"), "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1, sort_keys=True)
    print("%d pictures described, %d without a description%s" % (len(used), len(without), ": " + ", ".join(without[:8]) if without else ""))


if __name__ == "__main__":
    main()
